/**
 * A **general stabilizer code**, built from nothing but a list of Pauli generators.
 *
 * A stabilizer code encoding k logical qubits into n physical ones is defined by an abelian
 * subgroup S ⊂ Pₙ of the Pauli group, generated by r = n − k independent, mutually commuting
 * Paulis. The code space is their joint +1 eigenspace. From that single object everything
 * follows by GF(2) symplectic linear algebra — no state vectors, no floating point:
 *
 *   • **Validity**  — the generators must pairwise commute (else no common eigenspace) and be
 *     independent (else r is smaller than it looks). Both are rank/inner-product checks.
 *   • **Logical operators**  — the normaliser N(S) (Paulis commuting with all of S) has
 *     dimension n + k; quotienting out S leaves a 2k-dimensional symplectic space whose
 *     canonical symplectic basis is the k logical pairs (X̄ᵢ, Z̄ᵢ), found by symplectic
 *     Gram–Schmidt.
 *   • **Distance**  — d = min weight of a logical operator, i.e. of an element of N(S) \ S.
 *     Computed *exactly* by enumerating the normaliser. d fixes the correctable weight
 *     t = ⌊(d−1)/2⌋ and the label [[n, k, d]].
 *   • **Syndrome**  — an error E's syndrome is the bit vector of symplectic products
 *     ⟨gᵢ, E⟩; it is the only information a decoder ever sees.
 *
 * This turns the Steane-specific and surface-specific code modules of the lab into one engine
 * that ingests *any* code as data. See `codeZoo.ts` for the catalogue it powers.
 */

import {
  type SymPauli, parsePauli, symplectic, multiply, toVec, fromVec, identity,
} from './pauli';
import { rref, rank, nullspace, reduceVec, inRowSpace } from './gf2';

export interface CodeValidity {
  ok: boolean;
  commuting: boolean;
  independent: boolean;
  /** First non-commuting pair (indices) if any. */
  clash?: [number, number];
  issues: string[];
}

export class StabilizerCode {
  readonly n: number;
  readonly r: number; // number of independent stabilizer generators = n − k
  readonly k: number; // logical qubits
  readonly gens: SymPauli[]; // the (independent) stabilizer generators
  readonly logicalX: SymPauli[]; // length k
  readonly logicalZ: SymPauli[]; // length k
  private readonly normBasis: number[][]; // basis of the normaliser N(S), dim n + k
  private readonly sRref: { R: number[][]; pivots: number[] }; // for S-membership tests
  private _distance = -1;

  constructor(stabilizerStrings: string[]) {
    if (stabilizerStrings.length === 0) throw new Error('a code needs at least one generator');
    const parsed = stabilizerStrings.map(parsePauli);
    this.n = parsed[0].x.length;
    for (const g of parsed) if (g.x.length !== this.n) throw new Error('generators differ in length');

    // Reduce to an independent generating set (keep the given generators where possible).
    const chosen: SymPauli[] = [];
    const chosenVecs: number[][] = [];
    for (const g of parsed) {
      const test = [...chosenVecs, toVec(g)];
      if (rank(test) > chosenVecs.length) { chosen.push(g); chosenVecs.push(toVec(g)); }
    }
    this.gens = chosen;
    this.r = chosen.length;
    this.k = this.n - this.r;
    this.sRref = rref(chosenVecs);

    // Normaliser N(S) = { P : ⟨gᵢ, P⟩ = 0 ∀i }. In symplectic coordinates ⟨g, P⟩ = gz·px + gx·pz,
    // so P's vector [px|pz] must lie in the null space of the "swapped" generator rows [gz|gx].
    const constraint = chosen.map((g) => [...g.z, ...g.x]);
    this.normBasis = nullspace(constraint, 2 * this.n);

    // Logical operators: pick 2k normaliser vectors independent from S, then symplectic-pair.
    const { logicalX, logicalZ } = this.buildLogicals();
    this.logicalX = logicalX;
    this.logicalZ = logicalZ;
  }

  /** Validate that the generators commute and are independent. */
  validate(allStrings: string[]): CodeValidity {
    const parsed = allStrings.map(parsePauli);
    const issues: string[] = [];
    let commuting = true;
    let clash: [number, number] | undefined;
    for (let i = 0; i < parsed.length; i++) {
      for (let j = i + 1; j < parsed.length; j++) {
        if (symplectic(parsed[i], parsed[j]) !== 0) {
          commuting = false;
          if (!clash) clash = [i, j];
        }
      }
    }
    if (!commuting) issues.push(`generators ${clash![0] + 1} and ${clash![1] + 1} anticommute`);
    const independent = rank(parsed.map(toVec)) === parsed.length;
    if (!independent) issues.push(`generators are dependent (rank ${rank(parsed.map(toVec))} < ${parsed.length})`);
    return { ok: commuting && independent, commuting, independent, clash, issues };
  }

  /** Extract k symplectic pairs (X̄ᵢ, Z̄ᵢ) of logical operators from the normaliser. */
  private buildLogicals(): { logicalX: SymPauli[]; logicalZ: SymPauli[] } {
    const need = 2 * this.k;
    if (need === 0) return { logicalX: [], logicalZ: [] };
    // Collect 2k normaliser vectors that are independent from S (⇒ genuine logical classes).
    const combined = this.gens.map(toVec); // start from the stabilizer row space
    const logicals: SymPauli[] = [];
    for (const v of this.normBasis) {
      if (logicals.length === need) break;
      if (rank([...combined, v]) > combined.length) { combined.push(v); logicals.push(fromVec(v)); }
    }
    // Symplectic Gram–Schmidt: pull out conjugate pairs ⟨X̄, Z̄⟩ = 1, cleaning the rest.
    const pool = logicals.slice();
    const Xs: SymPauli[] = [], Zs: SymPauli[] = [];
    while (pool.length) {
      const a = pool.shift()!;
      const bi = pool.findIndex((b) => symplectic(a, b) === 1);
      if (bi < 0) continue; // central mod S — cannot happen for a nondegenerate form
      const b = pool.splice(bi, 1)[0];
      Xs.push(a); Zs.push(b);
      for (let i = 0; i < pool.length; i++) {
        const cb = symplectic(pool[i], b), ca = symplectic(pool[i], a);
        if (cb) pool[i] = multiply(pool[i], a);
        if (ca) pool[i] = multiply(pool[i], b);
      }
    }
    return { logicalX: Xs, logicalZ: Zs };
  }

  /** Is P a member of the stabilizer group S (up to phase)? */
  inStabilizer(p: SymPauli): boolean {
    return reduceVec(toVec(p), this.sRref.R, this.sRref.pivots).every((b) => b === 0);
  }

  /** Is P in the normaliser N(S) (commutes with every stabilizer)? */
  inNormalizer(p: SymPauli): boolean {
    return this.gens.every((g) => symplectic(g, p) === 0);
  }

  /** A P is a *non-trivial logical* iff it commutes with S but is not itself in S. */
  isLogical(p: SymPauli): boolean {
    return this.inNormalizer(p) && !this.inStabilizer(p);
  }

  /** The syndrome of an error E: the bit ⟨gᵢ, E⟩ for each generator (0 ⇔ commutes). */
  syndrome(e: SymPauli): number[] {
    return this.gens.map((g) => symplectic(g, e));
  }

  /** Syndrome packed into an integer key (MSB = first generator). */
  syndromeKey(e: SymPauli): number {
    let key = 0;
    for (const g of this.gens) key = (key << 1) | symplectic(g, e);
    return key;
  }

  /** Exact code distance d = min weight over N(S) \ S. Enumerates the normaliser; falls back
   *  to a weight-bounded search when the normaliser is too large to enumerate whole. */
  distance(): number {
    if (this._distance >= 0) return this._distance;
    if (this.k === 0) return (this._distance = Infinity); // no logical operators
    const m = this.normBasis.length; // n + k
    let best = Infinity;
    if (m <= 22) {
      // Full enumeration of the normaliser via Gray-code combinations of its basis.
      const acc = new Array(2 * this.n).fill(0);
      let prev = 0;
      for (let g = 1; g < (1 << m); g++) {
        const gray = g ^ (g >> 1);
        const flip = gray ^ prev; prev = gray;
        const bit = 31 - Math.clz32(flip); // exactly one bit changes
        const bv = this.normBasis[bit];
        for (let j = 0; j < acc.length; j++) acc[j] ^= bv[j];
        // weight of the Pauli (x_j OR z_j).
        let w = 0;
        for (let j = 0; j < this.n; j++) if (acc[j] || acc[j + this.n]) w++;
        if (w > 0 && w < best) {
          if (!reduceVec(acc, this.sRref.R, this.sRref.pivots).every((b) => b === 0)) best = w;
        }
      }
    } else {
      // Large normaliser: search increasing-weight logical representatives directly.
      best = this.boundedDistance();
    }
    return (this._distance = best);
  }

  /** Distance by increasing-weight enumeration of Paulis, stopping at the first logical. */
  private boundedDistance(): number {
    for (let w = 1; w <= this.n; w++) {
      let found = false;
      const combos = kSubsets(this.n, w);
      for (const support of combos) {
        // 3^w choices of X/Y/Z on the support.
        const total = 3 ** w;
        for (let c = 0; c < total; c++) {
          const p = identity(this.n);
          let cc = c;
          for (const q of support) {
            const t = cc % 3; cc = (cc / 3) | 0;
            if (t === 0) p.x[q] = 1; else if (t === 1) p.z[q] = 1; else { p.x[q] = 1; p.z[q] = 1; }
          }
          if (this.isLogical(p)) { found = true; break; }
        }
        if (found) break;
      }
      if (found) return w;
    }
    return Infinity;
  }

  /** Correctable error weight t = ⌊(d − 1)/2⌋. */
  correctableWeight(): number {
    const d = this.distance();
    return Number.isFinite(d) ? Math.floor((d - 1) / 2) : Infinity;
  }

  /** [[n, k, d]] label. */
  label(): string {
    const d = this.distance();
    return `[[${this.n}, ${this.k}, ${Number.isFinite(d) ? d : '∞'}]]`;
  }

  /** Generators of the encoded |0…0⟩_L: the stabilizers together with the logical Z̄ᵢ (which
   *  fix each logical qubit to |0⟩). Used to prepare and cross-check codewords on the real
   *  CHP tableau simulator. */
  zeroLGenerators(): SymPauli[] {
    return [...this.gens, ...this.logicalZ];
  }

  /**
   * Knill–Laflamme test: does the code correct *every* Pauli error up to weight `t`? True iff
   * no two such errors share a syndrome unless their product is in the stabilizer (i.e. they
   * are the *same* error up to a harmless stabilizer). Returns the first violating pair found.
   */
  verifyKnillLaflamme(t: number): { ok: boolean; witness?: [SymPauli, SymPauli] } {
    const errors = enumeratePaulis(this.n, t);
    const bySyndrome = new Map<number, SymPauli[]>();
    for (const e of errors) {
      const key = this.syndromeKey(e);
      const bucket = bySyndrome.get(key);
      if (bucket) {
        for (const f of bucket) {
          // Same syndrome ⇒ product commutes with all stabilizers. Correctable iff it is IN S.
          if (!this.inStabilizer(multiply(e, f))) return { ok: false, witness: [e, f] };
        }
        bucket.push(e);
      } else bySyndrome.set(key, [e]);
    }
    return { ok: true };
  }

  /** True iff the code is a CSS code — every generator is purely X-type or purely Z-type. */
  isCSS(): boolean {
    return this.gens.every((g) => {
      const hasX = g.x.some((b) => b), hasZ = g.z.some((b) => b);
      return !(hasX && hasZ);
    });
  }
}

/** All size-`w` subsets of {0, …, n−1}. */
export function kSubsets(n: number, w: number): number[][] {
  const out: number[][] = [];
  const rec = (start: number, chosen: number[]) => {
    if (chosen.length === w) { out.push(chosen.slice()); return; }
    for (let i = start; i < n; i++) { chosen.push(i); rec(i + 1, chosen); chosen.pop(); }
  };
  rec(0, []);
  return out;
}

/** Every Pauli on n qubits of weight ≤ maxWeight (identity included). */
export function enumeratePaulis(n: number, maxWeight: number): SymPauli[] {
  const out: SymPauli[] = [identity(n)];
  for (let w = 1; w <= maxWeight; w++) {
    for (const support of kSubsets(n, w)) {
      const total = 3 ** w;
      for (let c = 0; c < total; c++) {
        const p = identity(n);
        let cc = c;
        for (const q of support) {
          const t = cc % 3; cc = (cc / 3) | 0;
          if (t === 0) p.x[q] = 1; else if (t === 1) p.z[q] = 1; else { p.x[q] = 1; p.z[q] = 1; }
        }
        out.push(p);
      }
    }
  }
  return out;
}

/** Convenience re-export for callers that just want the row-space membership predicate. */
export { inRowSpace };
